sections.css:
.container {
  position: relative;
  width: 100%;
  height: 100%;
}

.backgroundLayer {
  position: absolute;
  inset: 0;
  overflow: clip;
}

.backgroundLayer .background {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
